import java.util.*;

class Solution {
  public int mostBooked(int n, int[][] meetings) {
    Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));
    PriorityQueue<Integer> available = new PriorityQueue<>();
    for (int room = 0; room < n; room++) available.offer(room);
    // busy rooms ordered by (end time, room number)
    PriorityQueue<long[]> busy =
        new PriorityQueue<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
    int[] used = new int[n];
    for (int[] meeting : meetings) {
      long start = meeting[0], duration = meeting[1] - meeting[0];
      while (!busy.isEmpty() && busy.peek()[0] <= start) available.offer((int) busy.poll()[1]);
      int room;
      if (!available.isEmpty()) {
        room = available.poll();
        busy.offer(new long[] {start + duration, room});
      } else {
        // every room is busy: wait for the earliest-ending one (lowest number on ties); other rooms freeing at that
        // moment stay busy until then, so they must not be handed to later meetings early
        long[] first = busy.poll();
        room = (int) first[1];
        busy.offer(new long[] {first[0] + duration, room});
      }
      used[room]++;
    }
    int answer = 0;
    for (int room = 1; room < n; room++) if (used[room] > used[answer]) answer = room;
    return answer;
  }
}
